-- CoffeeGate incident lifecycle (incremental, safe to re-run)
SET search_path TO app_coffegate, public;

ALTER TABLE cg_incident ADD COLUMN IF NOT EXISTS description VARCHAR(2000);
ALTER TABLE cg_incident ADD COLUMN IF NOT EXISTS assignee VARCHAR(128);
ALTER TABLE cg_incident ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ;
ALTER TABLE cg_incident ADD COLUMN IF NOT EXISTS closed_at TIMESTAMPTZ;

UPDATE cg_incident SET updated_at = COALESCE(updated_at, created_at) WHERE updated_at IS NULL;

CREATE TABLE IF NOT EXISTS cg_incident_event (
  id VARCHAR(64) PRIMARY KEY,
  incident_id VARCHAR(64) NOT NULL REFERENCES cg_incident(id) ON DELETE CASCADE,
  at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  actor VARCHAR(128),
  action VARCHAR(64) NOT NULL,
  from_status VARCHAR(32),
  to_status VARCHAR(32),
  note VARCHAR(1024)
);

CREATE INDEX IF NOT EXISTS idx_cg_incident_event_inc ON cg_incident_event (incident_id, at DESC);

-- Seed history for existing incidents that have no events yet
INSERT INTO cg_incident_event (id, incident_id, at, actor, action, from_status, to_status, note)
SELECT
  'ev-seed-' || i.id,
  i.id,
  i.created_at,
  'system',
  'created',
  NULL,
  i.status,
  'Импорт существующей заявки'
FROM cg_incident i
WHERE NOT EXISTS (
  SELECT 1 FROM cg_incident_event e WHERE e.incident_id = i.id
);

